function getNK(n, k, arr) {
  if (n === 1) {
    return "1";
  }

  let f = factorial[n - 1];
  let prefix = arr[Math.floor((k - 1) / f)];
  k = k % f;
  k = k === 0 ? f : k;

  arr = arr.filter((ele) => ele !== prefix);

  if (k === 1) {
    return prefix + arr.join("");
  } else {
    return prefix + getNK(n - 1, k, arr);
  }
}

/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    let [n, k] = lines.map((ele) => parseInt(ele));

    console.log(getPermutation(n, k));

    lines.length = 0;
  }
});

function getPermutation(n, k) {
  if (n === 1) return "1";

  // 记录n!排列组合需要的成员
  let arr = new Array(n).fill(0).map((_, idx) => idx + 1);

  // 记录阶乘值
  let factorial = [0, 1];
  for (let i = 2; i <= n; i++) {
    factorial[i] = factorial[i - 1] * i;
  }

  let res = "";

  while (true) {
    // 第k个排列的开头数字prefix
    let prefix = arr[Math.floor((k - 1) / factorial[n - 1])];
    res += prefix;
    // 对应排列在开头为prefix的排列中的序号
    k = k % factorial[n - 1];
    if (k === 0) {
      k = factorial[n - 1];
    }

    // 开头为prefix的排列所需的成员
    arr = arr.filter((ele) => ele !== prefix);
    n--;
    if (k === 1) {
      res += arr.join("");
      break;
    }
  }
  return res;
}

